        enc_term_posns = posns.doc_encoded_posns(term_idx, doc_id=doc_id)
        labeled_posns[term] = enc_term_posns

    result = Terms(tfs, posns=labeled_posns,
                   doc_len=doc_len, encoded=True)
    return result


